import type {NpcBanter,NpcThoughtBook,NpcThoughts} from './npcChatterTypes';
/**
 * Ambient NPC thoughts and banter (Nov 1 2026): authored content only, consumed by lib/town/npcChatter.ts.
 * Every islander has a personal pool in their own voice (job, interests, where they stand); every area has a fallback pool;
 * banter pairs stand near each other and, where natural, share one small, correct football idea.
 * Rules (tests/npc-thoughts.cjs): one sentence, max 48 characters, kid-safe, no emoji, no control hints, no repeats anywhere.
 */
